class Workflow:
    def __init__(self, config, problem) -> None:
        self.config = config
        self.problem_text = problem
        self.llm = create(config)

        self.generate = operator.Generate(self.llm, self.problem_text)
        self.revise = operator.Revise(self.llm, self.problem_text)
        self.summarize = operator.Summarize(self.llm, self.problem_text)
        self.ensemble = operator.Ensemble(self.llm, self.problem_text)

    async def run_workflow(self):
        import asyncio
        import re

        # Phase 1: Initial Analysis and Entity Extraction
        entities = await self.generate(
            instruction="""Extract all named entities, numbers, and relationships from the passage.
            Format as a structured list with categories:
            - People: [names and roles]
            - Places: [locations and contexts]
            - Numbers: [values and what they represent]
            - Actions: [what happens and when]""",
            context=""
        )

        # Phase 2: Question Classification and Operation Identification
        question_analysis = await self.generate(
            instruction=f"""Classify the question type and identify required operations.
            Passage Entities: {entities}

            Question Types:
            - Arithmetic: Addition, subtraction, multiplication, division
            - Counting: How many times, how many different, etc.
            - Comparison: Greater than, less than, equal to, etc.
            - Span Extraction: Who did, what was, when did, etc.
            - Multi-step: Requires chaining multiple operations or facts

            Identify the specific operation(s) needed to solve the question.""",
            context=entities
        )

        # Phase 3: Contextual Mapping and Reference Resolution
        reference_mapping = await self.generate(
            instruction=f"""Map question references to specific entities in the passage.
            Passage Entities: {entities}
            Question Analysis: {question_analysis}

            Resolve pronouns and partial names to their corresponding entities.""",
            context=question_analysis
        )

        # Phase 4: Operation Execution
        operation_results = await asyncio.gather(
            self.generate(
                instruction=f"""Perform arithmetic operations if required.
                Passage Entities: {entities}
                Question Analysis: {question_analysis}
                Reference Mapping: {reference_mapping}

                Ensure precise calculations and maintain full precision.""",
                context=reference_mapping
            ),
            self.generate(
                instruction=f"""Perform counting operations if required.
                Passage Entities: {entities}
                Question Analysis: {question_analysis}
                Reference Mapping: {reference_mapping}

                Count instances accurately and ensure no duplicates.""",
                context=reference_mapping
            ),
            self.generate(
                instruction=f"""Perform comparison operations if required.
                Passage Entities: {entities}
                Question Analysis: {question_analysis}
                Reference Mapping: {reference_mapping}

                Compare values and determine relationships.""",
                context=reference_mapping
            ),
            self.generate(
                instruction=f"""Perform span extraction if required.
                Passage Entities: {entities}
                Question Analysis: {question_analysis}
                Reference Mapping: {reference_mapping}

                Extract exact text spans that match the question.""",
                context=reference_mapping
            )
        )

        # Phase 5: Validation and Refinement
        refined_results = await asyncio.gather(
            *[self.revise(
                instruction=f"""Validate and refine the result.
                Original Result: {result}

                Check for errors, inconsistencies, and ensure the answer matches the expected format.""",
                context=result
            ) for result in operation_results]
        )

        # Phase 6: Final Answer Synthesis
        final_answer = await self.ensemble(
            instruction=f"""Synthesize the final answer from multiple candidate solutions.
            Refined Results: {refined_results}

            Select the most accurate and consistent answer.""",
            contexts_list=refined_results
        )

        return final_answer

class Workflow:
    def __init__(self, config, problem) -> None:
        self.config = config
        self.problem_text = problem
        self.llm = create(config)

        self.generate = operator.Generate(self.llm, self.problem_text)
        self.revise = operator.Revise(self.llm, self.problem_text)
        self.summarize = operator.Summarize(self.llm, self.problem_text)
        self.ensemble = operator.Ensemble(self.llm, self.problem_text)
        self.programmer = operator.Programmer(self.llm, self.problem_text)
        self.decompose = operator.Decompose(self.llm, self.problem_text)

    async def run_workflow(self):
        import asyncio
        import re
        from collections import defaultdict

        # STEP 1: Deep Structural Decomposition
        decomposition_instruction = """
        Break down this Bengali word problem into atomic, solvable subproblems. For each subproblem:
        - Assign a unique ID (e.g., "SP1", "SP2")
        - Describe what needs to be calculated or determined
        - Specify dependencies (other subproblem IDs that must be solved first)
        - Classify type: "compute" (requires calculation), "interpret" (requires semantic understanding), "validate" (requires checking constraints), or "relate" (requires combining results)
        - Extract and tag all entities, units, and numerical values involved
        - Note any implicit constraints (e.g., non-negative values, integer-only answers)

        Example format:
        [
          {
            "id": "SP1",
            "description": "Calculate Carlos's total cost: 3 hours × 30 টাকা/ঘণ্টা",
            "dependencies": "",
            "type": "compute",
            "entities": ["Carlos", "30 টাকা/ঘণ্টা", "3 ঘণ্টা"],
            "units": ["টাকা"],
            "constraints": ["non-negative"]
          }
        ]

        Ensure the decomposition reflects the causal and temporal structure of the problem.
        """

        subproblems = await self.decompose(
            instruction=decomposition_instruction,
            context=""
        )

        # Build dependency graph
        dependency_graph = {sp['id']: sp.get('dependencies', '').split(',') if sp.get('dependencies') else [] for sp in subproblems}
        solved = {}
        results_log = []

        # Topological sort helper
        def get_execution_order(graph):
            indegree = defaultdict(int)
            for node, deps in graph.items():
                for dep in deps:
                    if dep.strip():
                        indegree[node] += 1
            queue = [node for node in graph if indegree[node] == 0]
            order = []
            while queue:
                node = queue.pop(0)
                order.append(node)
                for n, deps in graph.items():
                    if node in [d.strip() for d in deps]:
                        indegree[n] -= 1
                        if indegree[n] == 0:
                            queue.append(n)
            return order

        execution_order = get_execution_order(dependency_graph)

        # STEP 2: Solve Subproblems in Dependency Order
        for sp_id in execution_order:
            sp = next(s for s in subproblems if s['id'] == sp_id)

            # Build context from dependencies
            dep_context = "\n".join([f"{dep_id}: {solved[dep_id]}" for dep_id in dependency_graph[sp_id] if dep_id.strip() and dep_id in solved])

            # Route based on type
            if sp['type'] == 'compute':
                compute_instruction = f"""
                Generate Python code to solve: {sp['description']}

                Context from dependencies:
                {dep_context}

                Entities and units involved: {sp.get('entities', [])}
                Constraints: {sp.get('constraints', [])}

                Requirements:
                - Use exact arithmetic
                - Track units explicitly in comments
                - Validate against constraints (e.g., non-negative)
                - Return only the final numerical result
                """

                result = await self.programmer(
                    instruction=compute_instruction,
                    context=dep_context
                )

                # Extract numerical result
                match = re.search(r'[-+]?\d*\.\d+|\d+', result)
                if match:
                    solved[sp_id] = match.group()
                else:
                    solved[sp_id] = "ERROR: No numerical result found"

            elif sp['type'] == 'interpret':
                interpret_instruction = f"""
                Resolve semantic ambiguity in: {sp['description']}

                Context: {dep_context}
                Problem text: {self.problem_text}

                Output format: "Interpretation: [clear restatement of meaning]"
                """
                result = await self.generate(
                    instruction=interpret_instruction,
                    context=dep_context
                )
                solved[sp_id] = result

            elif sp['type'] == 'validate':
                validate_instruction = f"""
                Check if {sp['description']} holds given:
                {dep_context}

                Return "VALID" or "INVALID: [reason]"
                """
                result = await self.generate(
                    instruction=validate_instruction,
                    context=dep_context
                )
                solved[sp_id] = result

            elif sp['type'] == 'relate':
                relate_instruction = f"""
                Combine these results to answer: {sp['description']}

                Results: {dep_context}

                Return only the final numerical answer.
                """
                result = await self.ensemble(
                    instruction=relate_instruction,
                    contexts_list=[dep_context]
                )
                solved[sp_id] = result

            # Validation step for all types
            validation_instruction = f"""
            Validate this result for subproblem {sp_id}: {solved[sp_id]}

            Against original problem: {self.problem_text}
            Constraints: {sp.get('constraints', [])}
            Expected unit: {sp.get('units', ['unknown'])[0] if sp.get('units') else 'unknown'}

            If invalid, explain why. If valid, return "OK".
            """

            validation = await self.revise(
                instruction=validation_instruction,
                context=str(solved[sp_id])
            )

            if "OK" not in validation and "VALID" not in validation:
                # Retry with feedback
                retry_instruction = f"""
                Previous attempt failed validation: {validation}

                Revised approach for: {sp['description']}
                Context: {dep_context}
                Constraints: {sp.get('constraints', [])}
                """

                if sp['type'] == 'compute':
                    result = await self.programmer(
                        instruction=retry_instruction,
                        context=dep_context
                    )
                    match = re.search(r'[-+]?\d*\.\d+|\d+', result)
                    solved[sp_id] = match.group() if match else "ERROR: Retry failed"
                else:
                    result = await self.generate(
                        instruction=retry_instruction,
                        context=dep_context
                    )
                    solved[sp_id] = result

            results_log.append(f"{sp_id}: {solved[sp_id]}")

        # STEP 3: Final Answer Synthesis
        final_synthesis_instruction = f"""
        Given all subproblem results:
        {'; '.join(results_log)}

        And original question: {self.problem_text}

        Synthesize the final answer by:
        1. Identifying which subproblem(s) directly answer the main question
        2. Cross-checking unit consistency
        3. Verifying no constraints are violated
        4. Returning ONLY the final numerical value (no units, no text)

        If multiple candidates exist, use ensemble to select the most consistent.
        """

        if len(results_log) == 1:
            final_answer = solved[execution_order[0]]
        else:
            final_answer = await self.ensemble(
                instruction=final_synthesis_instruction,
                contexts_list=results_log
            )

        # Extract final numerical answer
        final_match = re.search(r'[-+]?\d*\.\d+|\d+', str(final_answer))
        if final_match:
            return final_match.group()
        else:
            # Fallback: return first numerical result
            for result in results_log:
                match = re.search(r'[-+]?\d*\.\d+|\d+', result)
                if match:
                    return match.group()
            return "0"  # Ultimate fallback

class Workflow:
    def __init__(self, config, problem) -> None:
        self.config = config
        self.problem_text = problem
        self.llm = create(config)

        self.generate = operator.Generate(self.llm, self.problem_text)
        self.revise = operator.Revise(self.llm, self.problem_text)
        self.summarize = operator.Summarize(self.llm, self.problem_text)
        self.ensemble = operator.Ensemble(self.llm, self.problem_text)

    async def run_workflow(self):
        import asyncio

        # Initial analysis: Extract entities and classify question type
        extraction_task = self.generate(
            instruction="""Extract all entities, numbers, and relationships from the passage:
            - Entities: Names, places, organizations, etc.
            - Numbers: Values and what they represent
            - Relationships: Connections between entities and numbers
            Format as a structured list.""",
            context=""
        )
        classification_task = self.generate(
            instruction="""Classify the question type and identify required operations:
            - Is it arithmetic, counting, comparison, or span extraction?
            - What operations are implied by the question phrasing?""",
            context=""
        )
        extraction, classification = await asyncio.gather(extraction_task, classification_task)

        # Parallel processing: Resolve references and validate operations
        reference_resolution = self.revise(
            instruction=f"""Resolve pronouns and partial names to specific entities:
            Passage context: {extraction}
            Ensure all references are mapped correctly.""",
            context=extraction
        )
        operation_validation = self.revise(
            instruction=f"""Validate the identified operations:
            Classification: {classification}
            Ensure operations align with the question requirements.""",
            context=classification
        )
        resolved_references, validated_operations = await asyncio.gather(reference_resolution, operation_validation)

        # Conditional execution based on operation type
        if "arithmetic" in validated_operations.lower():
            result = await self.generate(
                instruction=f"""Perform arithmetic operations:
                Extracted numbers: {resolved_references}
                Operations: {validated_operations}
                Show all steps and maintain precision.""",
                context=resolved_references
            )
        elif "counting" in validated_operations.lower():
            result = await self.generate(
                instruction=f"""Count instances of entities or events:
                Extracted entities: {resolved_references}
                Operations: {validated_operations}
                Count carefully and verify.""",
                context=resolved_references
            )
        elif "comparison" in validated_operations.lower():
            result = await self.generate(
                instruction=f"""Compare values or spans:
                Extracted data: {resolved_references}
                Operations: {validated_operations}
                Clearly state which is greater/longer/etc.""",
                context=resolved_references
            )
        else:  # Span extraction
            result = await self.generate(
                instruction=f"""Extract exact text spans matching the question:
                Passage context: {resolved_references}
                Operations: {validated_operations}
                Ensure the span matches exactly as it appears.""",
                context=resolved_references
            )

        # Synthesis and validation
        final_answer = await self.ensemble(
            instruction=f"""Select the best-formatted answer:
            Candidate: {result}
            Ensure compliance with expected format (number, date, or exact span).""",
            contexts_list=[result]
        )

        return final_answer

